const potionsForPlayer = () => new Promise(function(resolve) {
  let enoughPotions = false;
  for (let potions = 0; potions <= 2; potions++) {
    if (potions === 2) {
      enoughPotions = true;
    }
  }
  resolve(enoughPotions);
  console.log("Player picked up two health potions");
});
const isEnoughPotionsToHeal = potions => new Promise(function(resolve) {
  if (potions) {
    resolve("Nice! Your health is restored!");
  } else {
    reject("Pick up one more potion.");
  }
});
const healMyPlayer = () => {
  const hasEnoughPotions = potionsForPlayer();
  const response = isEnoughPotionsToHeal(hasEnoughPotions);
  console.log(response);
};
healMyPlayer();

